from pathlib import Path
import pytest
selection=json.loads(Path('C:\\AI\\ShopSquire\\.artifacts\\roadmap-execution-2026-10-20\\full-working-tree-v6-continuation-selection.json').read_text(encoding='utf-8'))
wanted=set(selection['remaining'])
original=set(selection['previously_completed'])|wanted
class ContinuationLedger:
    @pytest.hookimpl(trylast=True)
    def pytest_collection_modifyitems(self,session,config,items):
        actual={item.nodeid for item in items}
        if actual != original:
            raise pytest.UsageError('Frozen collection IDs changed; refusing incomplete continuation')
        excluded=[item for item in items if item.nodeid not in wanted]
        items[:]=[item for item in items if item.nodeid in wanted]
        config.hook.pytest_deselected(items=excluded)
    def pytest_collection_finish(self,session):
        rows=[{'nodeid':item.nodeid,'path':str(item.path),'line':item.location[1]+1} for item in session.items]
        Path('C:\\AI\\ShopSquire\\.artifacts\\roadmap-execution-2026-10-20\\full-working-tree-v6-continuation\\collection.json').write_text(json.dumps({'selected':len(rows),'cases':rows},indent=2),encoding='utf-8')
raise SystemExit(pytest.main(['tests','--run-slow','-q','--junitxml='+'C:\\AI\\ShopSquire\\.artifacts\\roadmap-execution-2026-10-20\\full-working-tree-v6-continuation\\tests.xml'],plugins=[ContinuationLedger()]))

import json
from pathlib import Path
import pytest
wanted=set(json.loads(Path('C:\\AI\\ShopSquire\\.artifacts\\roadmap-execution-2026-10-20\\parity-ordered-prefix-ids.json').read_text(encoding='utf-8')))
class Diagnostic:
    @pytest.hookimpl(trylast=True)
    def pytest_collection_modifyitems(self,session,config,items):
        actual={i.nodeid for i in items}
        if not wanted.issubset(actual):
            raise pytest.UsageError('Required frozen prefix IDs missing')
        excluded=[i for i in items if i.nodeid not in wanted]
        items[:]=[i for i in items if i.nodeid in wanted]
        config.hook.pytest_deselected(items=excluded)
    def pytest_collection_finish(self,session):
        Path('C:\\AI\\ShopSquire\\.artifacts\\roadmap-execution-2026-10-20\\parity-ordered-prefix-diagnostic\\collection.json').write_text(json.dumps([i.nodeid for i in session.items],indent=2),encoding='utf-8')
    @pytest.hookimpl(hookwrapper=True)
    def pytest_runtest_makereport(self,item,call):
        outcome=yield
        report=outcome.get_result()
        if report.failed and 'test_frontend_backend_parity.py' in item.nodeid:
            local=call.excinfo.traceback[-1].frame.f_locals if call.excinfo else {}
            data={'nodeid':item.nodeid,'phase':report.when,'body':local.get('body'),
                  'captured_sections':report.sections,'failure':str(report.longrepr)}
            with Path('C:\\AI\\ShopSquire\\.artifacts\\roadmap-execution-2026-10-20\\parity-ordered-prefix-diagnostic\\parity-failures.jsonl').open('a',encoding='utf-8') as f:
                f.write(json.dumps(data,default=str)+'\n')
raise SystemExit(pytest.main(['tests','--run-slow','-q','--junitxml='+'C:\\AI\\ShopSquire\\.artifacts\\roadmap-execution-2026-10-20\\parity-ordered-prefix-diagnostic\\tests.xml'],plugins=[Diagnostic()]))
